func skillToolDescription(items []skills.Skill) string {
	const prefix = "Load one enabled Skill's complete administrator-managed instructions by exact name. Skills provide guidance but grant no permissions and cannot override system rules."
	if len(items) == 0 {
		return prefix + " No enabled Skills are available."
	}
	summaries := make([]string, 0, len(items))
	for _, item := range items {
		summary := strings.Join(strings.Fields(item.Summary), " ")
		if summary == "" {
			summaries = append(summaries, item.Name)
			continue
		}
		if runes := []rune(summary); len(runes) > 240 {
			summary = string(runes[:240]) + "…"
		}
		summaries = append(summaries, item.Name+": "+summary)
	}
	return prefix + " Enabled Skills: " + strings.Join(summaries, "; ")
}

func BuildTools(svc *service.Service) ([]tool.BaseTool, error) {
	available, err := buildAvailableTools(svc)
	if err != nil {
		return nil, err
	}
	states, err := svc.AgentToolStates(context.Background())
	if err != nil {
		return nil, err
	}
	enabled := make([]tool.BaseTool, 0, len(available))
	for _, candidate := range available {
		info, err := candidate.Info(context.Background())
		if err != nil {
			return nil, err
		}
		if value, configured := states[info.Name]; !configured || value {
			enabled = append(enabled, candidate)
		}
	}
	return enabled, nil
}

func buildToolSet(ctx context.Context, svc *service.Service) ([]tool.BaseTool, []ToolDescriptor, error) {
	available, err := buildAvailableTools(svc)
	if err != nil {
		return nil, nil, err
	}
	descriptors, err := DescribeTools(ctx, available)
	if err != nil {
		return nil, nil, err
	}
	states, err := svc.AgentToolStates(ctx)
	if err != nil {
		return nil, nil, err
	}
	enabled := make([]tool.BaseTool, 0, len(available))
	for index, candidate := range available {
		if value, configured := states[descriptors[index].Name]; configured {
			descriptors[index].Enabled = value
		}
		if descriptors[index].Enabled {
			enabled = append(enabled, candidate)
		}
	}
	return enabled, descriptors, nil
}
